/**
 * W3a ORIGINAL Three.js articulated demonstration rig.
 *
 * Every mesh here is procedurally generated by MagicMirror code. No FBX/GLB,
 * Z-Anatomy/BodyParts3D mesh, Google weight, camera image or user data is
 * loaded. It is a SCREEN-ALIGNED 2.5D teaching diagram, not a person's bones.
 *
 * The visible difference from the W0 proxy: the W0 renderer places each
 * observed line independently; here the forearm is a CHILD of the upper-arm
 * pivot, so its transform is inherited and the elbow stays coherent. Every
 * frame writes ABSOLUTE transforms from the immutable authored geometry,
 * never an accumulated delta, so there is no cumulative drift.
 */
import {
  BoxGeometry, CylinderGeometry, Group, Mesh, MeshStandardMaterial,
  SphereGeometry, type BufferGeometry, type Material,
} from "three";
import {
  displayDirection, type RigFrame, type RigSegmentState, type RigSide,
} from "./pose-to-rig";

export const ORIGINAL_RIG_LABEL =
  "Original 3D Motion Demo · Experimental · Uncalibrated";

export interface RigArmNodes {
  readonly shoulderPivot: Group;
  readonly elbowPivot: Group;
  /** Only used for a forearm observed WITHOUT a visible parent shoulder. */
  readonly independentPivot: Group;
  readonly upper: Mesh;
  readonly attachedFore: Mesh;
  readonly independentFore: Mesh;
  readonly shoulderJoint: Mesh;
  readonly elbowJoint: Mesh;
}

export interface OriginalRigNodes {
  readonly root: Group;
  readonly torso: Mesh;
  readonly left: RigArmNodes;
  readonly right: RigArmNodes;
}

function clampOpacity(opacity: number): number {
  return Number.isFinite(opacity) ? Math.min(0.95, Math.max(0.1, opacity)) : 0.65;
}

function segmentRadius(lengthPx: number): number {
  return Math.max(2, Math.min(14, lengthPx * 0.085));
}

/**
 * CylinderGeometry(1,1,1) spans local y in [-0.5, 0.5]. Placing the mesh at
 * length/2 and scaling y by `length` makes it extend from the pivot origin
 * to local y = length, i.e. exactly along the parent's +Y axis.
 */
function setSegment(mesh: Mesh, lengthPx: number): void {
  const radius = segmentRadius(lengthPx);
  mesh.position.set(0, lengthPx / 2, 0);
  mesh.scale.set(radius, lengthPx, radius);
}

export class OriginalArticulatedRig {
  readonly root = new Group();
  readonly nodes: OriginalRigNodes;
  private readonly geometries: BufferGeometry[] = [];
  private readonly materials: Material[] = [];
  private disposed = false;

  constructor() {
    const boneGeometry = new CylinderGeometry(1, 1, 1, 10);
    const jointGeometry = new SphereGeometry(1, 12, 8);
    const torsoGeometry = new BoxGeometry(1, 1, 1);
    const boneMaterial = new MeshStandardMaterial({
      color: "#e9d9b4", metalness: 0.12, roughness: 0.48,
      transparent: true, opacity: 0.65, depthWrite: false,
    });
    const jointMaterial = new MeshStandardMaterial({
      color: "#c79a53", metalness: 0.25, roughness: 0.4,
      transparent: true, opacity: 0.85, depthWrite: false,
    });
    const torsoMaterial = new MeshStandardMaterial({
      color: "#8fa48c", metalness: 0.05, roughness: 0.7,
      transparent: true, opacity: 0.45, depthWrite: false,
    });
    this.geometries.push(boneGeometry, jointGeometry, torsoGeometry);
    this.materials.push(boneMaterial, jointMaterial, torsoMaterial);

    const makeSide = (): RigArmNodes => {
      const shoulderPivot = new Group();
      const elbowPivot = new Group();
      const independentPivot = new Group();
      const upper = new Mesh(boneGeometry, boneMaterial);
      const attachedFore = new Mesh(boneGeometry, boneMaterial);
      const independentFore = new Mesh(boneGeometry, boneMaterial);
      const shoulderJoint = new Mesh(jointGeometry, jointMaterial);
      const elbowJoint = new Mesh(jointGeometry, jointMaterial);

      elbowPivot.add(attachedFore, elbowJoint);
      shoulderPivot.add(upper, shoulderJoint, elbowPivot);
      independentPivot.add(independentFore);
      this.root.add(shoulderPivot, independentPivot);
      return {
        shoulderPivot, elbowPivot, independentPivot,
        upper, attachedFore, independentFore, shoulderJoint, elbowJoint,
      };
    };
    const torso = new Mesh(torsoGeometry, torsoMaterial);
    this.root.add(torso);
    this.nodes = { root: this.root, torso, left: makeSide(), right: makeSide() };
    this.root.name = "W3a-original-articulated-rig";
    this.reset();
  }

  /** Deterministic rest pose; all segments hidden. */
  reset(): void {
    for (const side of ["left", "right"] as const) {
      const nodes = this.nodes[side];
      nodes.shoulderPivot.position.set(0, 0, 0);
      nodes.shoulderPivot.rotation.set(0, 0, 0);
      nodes.elbowPivot.position.set(0, 0, 0);
      nodes.elbowPivot.rotation.set(0, 0, 0);
      nodes.independentPivot.position.set(0, 0, 0);
      nodes.independentPivot.rotation.set(0, 0, 0);
      for (const mesh of [nodes.upper, nodes.attachedFore, nodes.independentFore]) {
        mesh.position.set(0, 0, 0);
        mesh.scale.set(1, 1, 1);
      }
      for (const joint of [nodes.shoulderJoint, nodes.elbowJoint]) {
        joint.position.set(0, 0, 0);
        joint.scale.setScalar(1);
      }
    }
    this.nodes.torso.position.set(0, 0, 0);
    this.nodes.torso.rotation.set(0, 0, 0);
    this.nodes.torso.scale.set(1, 1, 1);
    this.hide();
  }

  /** Write ABSOLUTE transforms from one validated frame. No accumulation. */
  apply(frame: RigFrame, opacity: number): number {
    if (this.disposed) return 0;
    if (frame.status === "rejected" || frame.visibleSegments === 0) {
      this.hide();
      return 0;
    }
    const value = clampOpacity(opacity);
    for (const material of this.materials) {
      (material as MeshStandardMaterial).opacity = value *
        ((material as MeshStandardMaterial) === this.materials[1] ? 1 : 0.82);
    }

    for (const side of ["left", "right"] as const) {
      this.applySide(side, frame.arms[side]);
    }
    this.applyTorso(frame);
    this.root.updateMatrixWorld(true);
    return frame.visibleSegments;
  }

  private applySide(side: RigSide, arm: RigFrame["arms"][RigSide]): void {
    const nodes = this.nodes[side];
    const hideAttached = (): void => {
      nodes.shoulderPivot.visible = false;
      nodes.upper.visible = false;
      nodes.shoulderJoint.visible = false;
      nodes.elbowPivot.visible = false;
      nodes.attachedFore.visible = false;
      nodes.elbowJoint.visible = false;
    };
    const hideIndependent = (): void => {
      nodes.independentPivot.visible = false;
      nodes.independentFore.visible = false;
    };

    if (arm.upper) {
      hideIndependent();
      const upper = arm.upper;
      const radius = segmentRadius(upper.lengthPx);
      nodes.shoulderPivot.visible = true;
      nodes.shoulderPivot.position.set(upper.start.x, upper.start.y, 0);
      nodes.shoulderPivot.rotation.set(0, 0, upper.angleRadians - Math.PI / 2);
      nodes.upper.visible = true;
      setSegment(nodes.upper, upper.lengthPx);
      nodes.shoulderJoint.visible = true;
      nodes.shoulderJoint.scale.setScalar(radius * 1.55);
      nodes.elbowPivot.position.set(0, upper.lengthPx, 0);

      const fore = arm.fore;
      if (fore && fore.hierarchyAttached) {
        nodes.elbowPivot.visible = true;
        nodes.elbowPivot.rotation.set(0, 0, fore.parentRelativeRadians ?? 0);
        nodes.attachedFore.visible = true;
        setSegment(nodes.attachedFore, fore.lengthPx);
        nodes.elbowJoint.visible = true;
        nodes.elbowJoint.scale.setScalar(segmentRadius(fore.lengthPx) * 1.4);
      } else {
        nodes.elbowPivot.visible = false;
        nodes.elbowPivot.rotation.set(0, 0, 0);
        nodes.attachedFore.visible = false;
        nodes.elbowJoint.visible = false;
      }
      return;
    }

    // No visible parent: show ONLY the observed forearm as an independent
    // segment. No shoulder pivot, elbow hierarchy or hidden joint is invented.
    hideAttached();
    if (arm.fore) {
      const fore: RigSegmentState = arm.fore;
      nodes.independentPivot.visible = true;
      nodes.independentPivot.position.set(fore.start.x, fore.start.y, 0);
      nodes.independentPivot.rotation.set(0, 0, fore.angleRadians - Math.PI / 2);
      nodes.independentFore.visible = true;
      setSegment(nodes.independentFore, fore.lengthPx);
    } else {
      hideIndependent();
    }
  }

  private applyTorso(frame: RigFrame): void {
    const left = frame.arms.left.shoulder;
    const right = frame.arms.right.shoulder;
    if (!left || !right || !frame.pivot) {
      this.nodes.torso.visible = false;
      return;
    }
    const distance = Math.hypot(right.x - left.x, right.y - left.y);
    if (!Number.isFinite(distance) || distance < 2) {
      this.nodes.torso.visible = false;
      return;
    }
    this.nodes.torso.visible = true;
    this.nodes.torso.position.set(frame.pivot.x, frame.pivot.y, -0.5);
    this.nodes.torso.rotation.set(0, 0, displayDirection(left, right));
    this.nodes.torso.scale.set(distance, Math.max(2, distance * 0.42), 1);
  }

  /** Tracking loss / pause / mode switch: nothing invented stays onscreen. */
  hide(): void {
    for (const side of ["left", "right"] as const) {
      const nodes = this.nodes[side];
      nodes.shoulderPivot.visible = false;
      nodes.upper.visible = false;
      nodes.shoulderJoint.visible = false;
      nodes.elbowPivot.visible = false;
      nodes.attachedFore.visible = false;
      nodes.elbowJoint.visible = false;
      nodes.independentPivot.visible = false;
      nodes.independentFore.visible = false;
    }
    this.nodes.torso.visible = false;
    this.root.updateMatrixWorld(true);
  }

  get isDisposed(): boolean { return this.disposed; }

  /** Explicit GPU resource cleanup on camera stop / page exit / mode fallback. */
  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.hide();
    this.root.removeFromParent();
    for (const geometry of this.geometries) geometry.dispose();
    for (const material of this.materials) material.dispose();
    this.geometries.length = 0;
    this.materials.length = 0;
  }
}
